/**
 * The provider boundary contract.
 *
 *   Demo and live providers may obtain data differently, but everything above
 *   the provider boundary receives the same contract.
 *
 * These tests run equivalent inputs through both providers and assert the
 * results are shaped identically. The API provider is driven by a stubbed
 * `fetch` returning the same fixtures the demo provider reads, so any
 * divergence is the provider's doing rather than the data's.
 *
 * The diff case is checked against `demo-data/expected-diff.json`, which is
 * generated by the REAL backend diff service — a cross-language check, and the
 * one that would have caught the crash that motivated these tests.
 */
import { afterEach, beforeEach, describe, expect, it, vi } from "vitest";

import accountsFixture from "@demo-data/accounts.json";
import alertsFixture from "@demo-data/alerts.json";
import currentScan from "@demo-data/current-scan.json";
import expectedDiff from "@demo-data/expected-diff.json";
import previousScan from "@demo-data/previous-scan.json";
import { apiScanProvider } from "./apiScanProvider.js";
import { demoScanProvider } from "./demoScanProvider.js";

/** Structural fingerprint: key names and value *types*, not values. */
function shapeOf(value, depth = 0) {
  if (value === null || depth > 6) return value === null ? "null" : "…";
  if (Array.isArray(value)) return value.length ? [shapeOf(value[0], depth + 1)] : [];
  if (typeof value === "object") {
    return Object.fromEntries(
      Object.keys(value)
        .sort()
        .map((k) => [k, shapeOf(value[k], depth + 1)])
    );
  }
  return typeof value;
}

/** Route a stubbed fetch to the fixture the real API would return. */
function stubApi() {
  global.fetch = vi.fn(async (url) => {
    const path = String(url).replace(/^https?:\/\/[^/]+/, "");
    let body;
    if (path.startsWith("/scan?") || path === "/scan") {
      // Written out literally, because a stub that borrows saved-scan metadata
      // is a stub of an endpoint that does not exist. `GET /scan` returns the
      // scan payload plus the live-result fields and nothing else — no
      // `created_at`, no `as_of` (the provider normalizes that in), and a null
      // `scan_id` when the scan was not persisted. Spreading `currentScan`
      // here made the fake API generous enough to hide the demo provider
      // doing the same thing.
      body = {
        scan_id: null,
        summary: currentScan.summary,
        resources: currentScan.resources,
        alerts: alertsFixture.alerts,
        persisted: false,
        regions_failed: [],
        scanners_failed: [],
      };
    } else if (path.startsWith("/scans/diff")) {
      body = expectedDiff;
    } else if (path.startsWith("/scans/")) {
      body = currentScan;
    } else if (path.startsWith("/scans")) {
      body = {
        scans: [
          {
            scan_id: currentScan.scan_id,
            created_at: currentScan.created_at,
            resource_count: currentScan.resources.length,
            summary: currentScan.summary,
            vs_previous: expectedDiff.summary,
          },
          {
            scan_id: previousScan.scan_id,
            created_at: previousScan.created_at,
            resource_count: previousScan.resources.length,
            summary: previousScan.summary,
            vs_previous: null,
          },
        ],
      };
    } else if (path.startsWith("/accounts")) {
      body = accountsFixture;
    } else {
      throw new Error(`unstubbed path: ${path}`);
    }
    return { ok: true, status: 200, json: async () => body };
  });
}

beforeEach(stubApi);
afterEach(() => vi.restoreAllMocks());

describe("both providers satisfy the same contract", () => {
  it("declares the same method surface", () => {
    const methods = (p) =>
      Object.keys(p)
        .filter((k) => typeof p[k] === "function")
        .sort();
    expect(methods(demoScanProvider)).toEqual(methods(apiScanProvider));
  });

  it("declares the same capability keys", () => {
    expect(Object.keys(demoScanProvider.capabilities).sort()).toEqual(
      Object.keys(apiScanProvider.capabilities).sort()
    );
  });

  it.each([
    ["getScan", (p) => p.getScan(currentScan.scan_id)],
    ["listScans", (p) => p.listScans()],
    ["listAccounts", (p) => p.listAccounts()],
    ["compareScans", (p) => p.compareScans(previousScan.scan_id, currentScan.scan_id)],
  ])("%s returns the same shape from both providers", async (_name, call) => {
    const [demo, api] = await Promise.all([call(demoScanProvider), call(apiScanProvider)]);
    expect(shapeOf(demo)).toEqual(shapeOf(api));
  });

  it("runScan returns the same shape from both providers", async () => {
    // The demo deliberately simulates latency; don't wait it out for real.
    vi.useFakeTimers();
    const demoPromise = demoScanProvider.runScan();
    await vi.runAllTimersAsync();
    const demo = await demoPromise;
    vi.useRealTimers();

    const api = await apiScanProvider.runScan();
    expect(shapeOf(demo)).toEqual(shapeOf(api));

    // ...and the shape they agree on is a *live* scan, not a saved one. The
    // regression the old contract allowed, pinned here: the demo spread the
    // saved fixture, so it returned a real `scan_id` and carried `created_at`
    // along with it, and `ScanResult extends Scan` said that was correct.
    // Neither provider ran a scan that was saved, so neither has an id, and
    // saved-scan metadata belongs to saved scans only.
    for (const result of [demo, api]) {
      expect(result.scan_id).toBeNull();
      expect("created_at" in result).toBe(false);
      // `as_of` is the normalization that replaces it: required, because ages
      // have to be measured against when the scan ran. The endpoint sends no
      // timestamp, so each provider supplies its own.
      expect(typeof result.as_of).toBe("string");
      expect(Number.isNaN(Date.parse(result.as_of))).toBe(false);
    }

    // The demo's answer is its fixture's timestamp, not the current time. This
    // is what keeps the demo deterministic: stamping now would creep every age
    // in the table upward daily and outrun the committed screenshots.
    expect(demo.as_of).toBe(currentScan.created_at);
  });
});

describe("demo compareScans reproduces the real backend diff", () => {
  it("matches the backend's counts exactly", async () => {
    const diff = await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    expect(diff.summary).toEqual(expectedDiff.summary);
  });

  it("nests changed entries as {resource, changes} keyed by field", async () => {
    // The exact shape that was wrong before: a flat resource with an array.
    const diff = await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    const entry = diff.changed[0];

    expect(Object.keys(entry).sort()).toEqual(["changes", "resource"]);
    expect(Array.isArray(entry.changes)).toBe(false);
    expect(entry.resource.resource_id).toBeTruthy();

    for (const [field, delta] of Object.entries(entry.changes)) {
      expect(Object.keys(delta).sort()).toEqual(["from", "to"]);
      expect(delta.from).not.toEqual(delta.to);
      expect(["status", "risk_level"]).toContain(field);
    }
  });

  it("identifies the same added, removed, and changed resources", async () => {
    const diff = await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    const ids = (list, pick = (x) => x) => list.map((x) => pick(x).resource_id).sort();

    expect(ids(diff.added)).toEqual(ids(expectedDiff.added));
    expect(ids(diff.removed)).toEqual(ids(expectedDiff.removed));
    expect(ids(diff.changed, (c) => c.resource)).toEqual(
      ids(expectedDiff.changed, (c) => c.resource)
    );
  });
});

describe("the demo cannot reach the network", () => {
  it("makes no fetch calls for any read operation", async () => {
    vi.useFakeTimers();
    const scan = demoScanProvider.runScan();
    await vi.runAllTimersAsync();
    await scan;
    vi.useRealTimers();

    await demoScanProvider.listScans();
    await demoScanProvider.getScan(currentScan.scan_id);
    await demoScanProvider.compareScans(previousScan.scan_id, currentScan.scan_id);
    await demoScanProvider.listAccounts();
    await demoScanProvider.getCleanupActions();

    expect(global.fetch).not.toHaveBeenCalled();
  });

  it("refuses account and team writes with an explanatory error", async () => {
    await expect(demoScanProvider.createAccount({})).rejects.toThrow(/not available in the demo/i);
    await expect(demoScanProvider.listUsers()).rejects.toThrow(/not available in the demo/i);
  });
});

describe("demo cleanup preview walks the real gates", () => {
  // An unassociated Elastic IP is the one fixture eligible for release.
  const eligible = currentScan.resources.find(
    (r) => r.resource_type === "Elastic IP" && r.status === "unassociated"
  );
  const associated = currentScan.resources.find(
    (r) => r.resource_type === "Elastic IP" && r.status === "associated"
  );

  // Every fixture resource lives in a registered account, so a well-formed
  // request names one. The panel fills this in from the selected finding.
  const request = (over = {}) => ({
    action: "release_elastic_ip",
    resource_id: eligible.resource_id,
    confirm_resource_id: eligible.resource_id,
    region: eligible.region,
    account_id: eligible.account_id,
    dry_run: true,
    ...over,
  });

  it("returns a dry-run result for an eligible resource", async () => {
    const res = await demoScanProvider.executeCleanup(request());
    expect(res.status).toBe("dry_run");
    expect(res.dry_run).toBe(true);
    expect(res.detail).toMatch(/^Would release unassociated Elastic IP/);
  });

  it("rejects an unknown action before checking confirmation", async () => {
    // Matches the backend's ordering: catalog lookup precedes confirmation.
    await expect(
      demoScanProvider.executeCleanup(request({ action: "nuke_everything", confirm_resource_id: "x" }))
    ).rejects.toThrow(/Unsupported cleanup action/);
  });

  it("rejects a confirmation that does not match", async () => {
    await expect(
      demoScanProvider.executeCleanup(request({ confirm_resource_id: "not-the-id" }))
    ).rejects.toThrow(/Confirmation does not match/);
  });

  it("rejects a real resource id in the wrong region", async () => {
    // The service calls Describe* against one regional endpoint, so an id from
    // us-east-1 does not exist in us-west-2. The demo used to ignore region and
    // happily preview a release in a region the resource was never in — and in
    // regions that do not exist at all.
    await expect(
      demoScanProvider.executeCleanup(request({ region: "us-west-2" }))
    ).rejects.toThrow(/not found in us-west-2/);

    await expect(
      demoScanProvider.executeCleanup(request({ region: "us-east-3" }))
    ).rejects.toThrow(/not found in us-east-3/);
  });

  it("rejects a real resource id under the wrong account", async () => {
    // Same reasoning as region: the service resolves credentials from the named
    // account and describes the resource there. An id from the sandbox account
    // does not exist in the training account — and naming no account at all
    // means default credentials, which is a third account again.
    const other = currentScan.resources.find(
      (r) => r.account_id && r.account_id !== eligible.account_id
    );

    await expect(
      demoScanProvider.executeCleanup(request({ account_id: other.account_id }))
    ).rejects.toThrow(new RegExp(`not found in .* for account ${other.account_id}`));

    await expect(
      demoScanProvider.executeCleanup(request({ account_id: null }))
    ).rejects.toThrow(/not found in us-east-1\./);
  });

  it("rejects a resource that is not in the scan", async () => {
    await expect(
      demoScanProvider.executeCleanup(
        request({ resource_id: "eipalloc-000000000000", confirm_resource_id: "eipalloc-000000000000" })
      )
    ).rejects.toThrow(/not found/);
  });

  it("rejects a resource whose live state fails the precondition", async () => {
    await expect(
      demoScanProvider.executeCleanup(
        request({
          resource_id: associated.resource_id,
          confirm_resource_id: associated.resource_id,
        })
      )
    ).rejects.toThrow(/associated with a running resource/);
  });

  it("cannot execute for real, even with every other gate passed", async () => {
    await expect(demoScanProvider.executeCleanup(request({ dry_run: false }))).rejects.toThrow(
      /holds no AWS credentials/
    );
  });

  it("audits every attempt, including the refusals", async () => {
    const before = (await demoScanProvider.getCleanupAudit()).entries.length;
    await demoScanProvider.executeCleanup(request()).catch(() => {});
    await demoScanProvider.executeCleanup(request({ confirm_resource_id: "no" })).catch(() => {});

    const { entries } = await demoScanProvider.getCleanupAudit();
    expect(entries.length).toBe(before + 2);
    expect(entries[0].status).toBe("confirmation_mismatch"); // newest first
    expect(entries[1].status).toBe("dry_run");

    // The account the attempt targeted, not a hardcoded null. An audit trail
    // that cannot say which account was acted on is not an audit trail.
    expect(entries[1].account_id).toBe(eligible.account_id);

    // Only the two just recorded — the audit is shared module state, and an
    // earlier test legitimately logged a dry_run:false attempt (that refusal
    // is recorded as what it was: an attempt to execute for real).
    expect(entries.slice(0, 2).every((e) => e.dry_run === true)).toBe(true);
  });
});
